// Works on any array, but slow: scans one by one
int linearSearch(int[] nums, int target) {
    for (int i = 0; i < nums.length; i++) {
        if (nums[i] == target) return i;   // up to n comparisons
    }
    return -1;
}
// 1,000,000 elements -> up to 1,000,000 comparisons
