// Minimum eating speed so all piles finish within h hours.
int minEatingSpeed(int[] piles, int h) {
    int lo = 1, hi = Arrays.stream(piles).max().getAsInt();
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;          // candidate speed
        if (feasible(piles, h, mid)) hi = mid; // works -> try slower
        else lo = mid + 1;                     // too slow -> speed up
    }
    return lo;
}
boolean feasible(int[] piles, int h, int speed) {
    long hours = 0;
    for (int p : piles) hours += (p + speed - 1) / speed;  // ceil divide
    return hours <= h;
}

// piles={3,6,7,11}, h=8: speeds 1..11.
// feasible: F F F T T... -> binary search lands on speed 4.
```

