int[] searchRange(int[] nums, int target) {
    return new int[]{ bound(nums, target, true), bound(nums, target, false) };
}
int bound(int[] nums, int target, boolean first) {
    int lo = 0, hi = nums.length - 1, ans = -1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (nums[mid] == target) {
            ans = mid;
            if (first) hi = mid - 1; else lo = mid + 1;  // keep narrowing
        } else if (nums[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return ans;
}

// nums = {1,2,2,2,3,4,5}, target = 2
// first -> 1, last -> 3, count = 3 - 1 + 1 = 3
```

