int mySqrt(int n) {
    if (n < 2) return n;
    int lo = 1, hi = n, ans = 0;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        long sq = (long) mid * mid;        // long cast avoids overflow
        if (sq == n) return mid;
        else if (sq < n) { ans = mid; lo = mid + 1; }  // candidate, go bigger
        else hi = mid - 1;                 // too big, go smaller
    }
    return ans;                            // floor of sqrt(n)
}

// n = 17: lo=1,hi=17
// mid=9 -> 81>17 -> hi=8; mid=4 -> 16<17 -> ans=4,lo=5
// mid=6 -> 36>17 -> hi=5; mid=5 -> 25>17 -> hi=4 -> stop, return 4
